use std::collections::HashMap;
use std::sync::{Arc, RwLock};

/// Role-based access control metadata propagation for gRPC service
/// This module handles extracting user identity from metadata headers
/// and propagating audit trail information to downstream services.

#[derive(Debug, Clone, PartialEq)]
pub enum Role {
    Admin,
    User,
    Service,
    Anonymous,
}

#[derive(Debug, Clone)]
pub struct Identity {
    pub username: String,
    pub role: Role,
    pub session_id: String,
}

pub struct AuditLogger {
    entries: Arc<RwLock<Vec<String>>>,
}

impl AuditLogger {
    pub fn new() -> Self {
        AuditLogger {
            entries: Arc::new(RwLock::new(Vec::new())),
        }
    }

    pub fn log_access(&self, identity: &Identity, resource: &str) {
        let entry = format!("ACCESS: user={} role={:?} resource={}",
            identity.username, identity.role, resource);
        self.entries.write().unwrap().push(entry);
    }
}

/// Encodes a metadata value for gRPC header propagation.
/// gRPC metadata values must not contain certain characters.
/// We use percent-encoding for safety.
fn encode_metadata_value(raw: &str) -> String {
    let mut encoded = String::with_capacity(raw.len());
    for byte in raw.bytes() {
        match byte {
            // Allow printable ASCII except percent itself
            0x20..=0x24 | 0x26..=0x7E => encoded.push(byte as char),
            0x25 => encoded.push_str("%25"),
            _ => encoded.push_str(&format!("%{:02X}", byte)),
        }
    }
    encoded
}

/// Decodes a percent-encoded metadata value back to the original string.
fn decode_metadata_value(encoded: &str) -> String {
    let mut decoded = String::new();
    let bytes = encoded.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() {
            if let Ok(hex_str) = std::str::from_utf8(&bytes[i+1..i+3]) {
                if let Ok(byte_val) = u8::from_str_radix(hex_str, 16) {
                    decoded.push(byte_val as char);
                    i += 3;
                    continue;
                }
            }
        }
        decoded.push(bytes[i] as char);
        i += 1;
    }
    decoded
}

/// Constructs the outgoing metadata map for downstream gRPC calls.
/// This propagates identity context through the service mesh.
pub fn build_propagation_headers(identity: &Identity, trace_id: &str) -> HashMap<String, String> {
    let mut headers = HashMap::new();

    // Encode identity fields for safe header transport
    headers.insert(
        "x-identity-user".to_string(),
        encode_metadata_value(&identity.username),
    );
    headers.insert(
        "x-identity-role".to_string(),
        encode_metadata_value(&format!("{:?}", identity.role)),
    );
    headers.insert(
        "x-trace-id".to_string(),
        encode_metadata_value(trace_id),
    );
    headers.insert(
        "x-session-id".to_string(),
        encode_metadata_value(&identity.session_id),
    );

    headers
}

/// Formats the full HTTP/2 HEADERS frame payload from the metadata map.
/// This is used when manually constructing frames for the custom transport layer.
pub fn format_headers_payload(headers: &HashMap<String, String>) -> String {
    let mut payload = String::new();
    for (key, value) in headers {
        // Each header line in our wire format is "key: value\r\n"
        payload.push_str(&format!("{}: {}\r\n", key, value));
    }
    payload
}

/// Parses an incoming role claim from the authentication token.
/// The role string comes from the JWT claims after signature verification.
pub fn parse_role_from_claim(claim: &str) -> Role {
    match claim.trim().to_lowercase().as_str() {
        "admin" => Role::Admin,
        "user" => Role::User,
        "service" => Role::Service,
        _ => Role::Anonymous,
    }
}

/// Validates that a user with the given role can access the specified resource.
pub fn check_access(role: &Role, resource: &str) -> bool {
    match role {
        Role::Admin => true,
        Role::Service => resource.starts_with("/internal/"),
        Role::User => resource.starts_with("/api/") && !resource.contains("/admin/"),
        Role::Anonymous => resource == "/api/health" || resource == "/api/version",
    }
}

/// Main request handler that ties together auth, RBAC, and propagation.
pub fn handle_request(
    incoming_metadata: &HashMap<String, String>,
    resource: &str,
    logger: &AuditLogger,
) -> Result<HashMap<String, String>, String> {
    // Extract identity from incoming metadata (already verified by auth interceptor)
    let username = incoming_metadata
        .get("x-verified-user")
        .map(|v| decode_metadata_value(v))
        .unwrap_or_else(|| "anonymous".to_string());

    let role_claim = incoming_metadata
        .get("x-verified-role")
        .map(|v| decode_metadata_value(v))
        .unwrap_or_else(|| "anonymous".to_string());

    let session_id = incoming_metadata
        .get("x-session-id")
        .map(|v| decode_metadata_value(v))
        .unwrap_or_else(|| "none".to_string());

    let trace_id = incoming_metadata
        .get("x-trace-id")
        .map(|v| decode_metadata_value(v))
        .unwrap_or_else(|| generate_trace_id());

    let identity = Identity {
        username,
        role: parse_role_from_claim(&role_claim),
        session_id,
    };

    // Check RBAC
    if !check_access(&identity.role, resource) {
        return Err(format!("Access denied for role {:?} to {}", identity.role, resource));
    }

    // Log the access
    logger.log_access(&identity, resource);

    // Build propagation headers for downstream calls
    let propagation = build_propagation_headers(&identity, &trace_id);

    // Format for wire transport
    let _wire_payload = format_headers_payload(&propagation);

    Ok(propagation)
}

fn generate_trace_id() -> String {
    "trace-00000001".to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_flow() {
        let mut meta = HashMap::new();
        meta.insert("x-verified-user".to_string(), encode_metadata_value("alice"));
        meta.insert("x-verified-role".to_string(), encode_metadata_value("admin"));
        meta.insert("x-session-id".to_string(), encode_metadata_value("sess-123"));

        let logger = AuditLogger::new();
        let result = handle_request(&meta, "/api/data", &logger);
        assert!(result.is_ok());
    }

    #[test]
    fn test_access_denied() {
        let mut meta = HashMap::new();
        meta.insert("x-verified-user".to_string(), encode_metadata_value("bob"));
        meta.insert("x-verified-role".to_string(), encode_metadata_value("user"));

        let logger = AuditLogger::new();
        let result = handle_request(&meta, "/internal/secrets", &logger);
        assert!(result.is_err());
    }

    #[test]
    fn test_encoding_roundtrip() {
        let original = "hello world";
        let encoded = encode_metadata_value(original);
        let decoded = decode_metadata_value(&encoded);
        assert_eq!(original, decoded);
    }
}
